import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Stage — shared three.js viewport for every 3D rig: renderer, orbit camera
// (drag + auto-rotate), warm sun + soft shadows, a textured grass ground, and
// a library of PROCEDURAL canvas textures (wood, metal, asphalt, foliage,
// fabric, concrete, grass, plastic) that are UV-mapped with RepeatWrapping and
// paired bump maps for surface relief. No external image assets required.
// ---------------------------------------------------------------------------

export type TexName =
  | 'wood'
  | 'metal'
  | 'asphalt'
  | 'leaf'
  | 'fabric'
  | 'concrete'
  | 'grass'
  | 'plastic';

// ---- colour helpers ----
function toRGB(hex: number): [number, number, number] {
  return [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255];
}
function cl(v: number) {
  return Math.max(0, Math.min(255, v | 0));
}
function shade(hex: number, amt: number, sat = 1) {
  const [r, g, b] = toRGB(hex);
  return `rgb(${cl(r + amt)},${cl(g + amt * sat)},${cl(b + amt)})`;
}

// ---- procedural texture drawing (returns an HTMLCanvasElement) ----
function drawTexture(name: TexName, color: number, S = 128): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = c.height = S;
  const x = c.getContext('2d')!;
  const [r, g, b] = toRGB(color);
  x.fillStyle = `rgb(${r},${g},${b})`;
  x.fillRect(0, 0, S, S);
  const rnd = (a: number, bb: number) => a + Math.random() * (bb - a);

  if (name === 'wood') {
    for (let i = 0; i < 90; i++) {
      x.strokeStyle = shade(color, rnd(-26, 14));
      x.lineWidth = rnd(0.5, 1.6);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      for (let px = 0; px <= S; px += 8) x.lineTo(px, y + Math.sin(px * 0.08 + i) * 1.5);
      x.stroke();
    }
    for (let p = 0; p <= S; p += S / 4) {
      x.strokeStyle = shade(color, -34);
      x.lineWidth = 1.5;
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    for (let k = 0; k < 3; k++) {
      x.strokeStyle = shade(color, -30);
      x.beginPath();
      x.ellipse(rnd(0, S), rnd(0, S), rnd(2, 5), rnd(3, 7), 0, 0, Math.PI * 2);
      x.stroke();
    }
  } else if (name === 'metal') {
    for (let i = 0; i < 160; i++) {
      x.strokeStyle = shade(color, rnd(-22, 30));
      x.lineWidth = rnd(0.4, 1);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      x.lineTo(S, y);
      x.stroke();
    }
  } else if (name === 'asphalt') {
    for (let i = 0; i < 2600; i++) {
      x.fillStyle = shade(color, rnd(-34, 34));
      const s = rnd(0.6, 2.2);
      x.fillRect(rnd(0, S), rnd(0, S), s, s);
    }
  } else if (name === 'leaf') {
    for (let i = 0; i < 320; i++) {
      x.fillStyle = shade(color, rnd(-40, 34), 1.3);
      x.beginPath();
      x.arc(rnd(0, S), rnd(0, S), rnd(2.5, 7), 0, Math.PI * 2);
      x.fill();
    }
  } else if (name === 'fabric') {
    for (let p = 0; p < S; p += 3) {
      x.strokeStyle = shade(color, 12);
      x.globalAlpha = 0.35;
      x.beginPath();
      x.moveTo(p, 0);
      x.lineTo(p, S);
      x.stroke();
      x.strokeStyle = shade(color, -16);
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    x.globalAlpha = 1;
  } else if (name === 'concrete') {
    for (let i = 0; i < 1800; i++) {
      x.fillStyle = shade(color, rnd(-18, 22));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  } else if (name === 'grass') {
    for (let i = 0; i < 2200; i++) {
      x.strokeStyle = shade(color, rnd(-30, 26), 1.4);
      x.lineWidth = 1;
      const gx = rnd(0, S);
      const gy = rnd(0, S);
      x.beginPath();
      x.moveTo(gx, gy);
      x.lineTo(gx + rnd(-1.5, 1.5), gy - rnd(2, 5));
      x.stroke();
    }
  } else if (name === 'plastic') {
    const grad = x.createLinearGradient(0, 0, 0, S);
    grad.addColorStop(0, shade(color, 30));
    grad.addColorStop(0.5, shade(color, 4));
    grad.addColorStop(1, shade(color, -22));
    x.fillStyle = grad;
    x.fillRect(0, 0, S, S);
    for (let i = 0; i < 400; i++) {
      x.fillStyle = shade(color, rnd(-8, 8));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  }
  return c;
}

const _texCache = new Map<string, THREE.CanvasTexture>();
function getTex(three: typeof THREE, name: TexName, color: number, rx: number, ry: number) {
  const key = `${name}:${color}:${rx}:${ry}`;
  const hit = _texCache.get(key);
  if (hit) return hit;
  const tex = new three.CanvasTexture(drawTexture(name, color));
  tex.wrapS = tex.wrapT = three.RepeatWrapping;
  tex.repeat.set(rx, ry);
  tex.anisotropy = 4;
  (tex as unknown as { colorSpace: string }).colorSpace = (three as unknown as { SRGBColorSpace: string }).SRGBColorSpace;
  _texCache.set(key, tex);
  return tex;
}

// ---- material + geometry helpers ----
export interface MatOpts {
  rough?: number;
  metal?: number;
  flat?: boolean;
  emissive?: number;
  opacity?: number;
  tex?: TexName;
  repeat?: [number, number];
  bump?: number;
}
export function mat(three: typeof THREE, color: number, o: MatOpts = {}) {
  const m = new three.MeshStandardMaterial({
    color: o.tex ? 0xffffff : color,
    roughness: o.rough ?? 0.82,
    metalness: o.metal ?? 0.0,
    flatShading: o.flat ?? false,
    emissive: o.emissive ?? 0x000000,
    transparent: o.opacity != null,
    opacity: o.opacity ?? 1,
  });
  if (o.tex) {
    const [rx, ry] = o.repeat ?? [1, 1];
    const t = getTex(three, o.tex, color, rx, ry);
    m.map = t;
    m.bumpMap = t;
    m.bumpScale = o.bump ?? 0.02;
  }
  return m;
}
export function box(
  three: typeof THREE,
  dims: [number, number, number],
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number } = {},
) {
  const m = new three.Mesh(new three.BoxGeometry(...dims), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function cyl(
  three: typeof THREE,
  rTop: number,
  rBot: number,
  h: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number; seg?: number } = {},
) {
  const m = new three.Mesh(new three.CylinderGeometry(rTop, rBot, h, o.seg ?? 16), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function ball(
  three: typeof THREE,
  r: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts = {},
) {
  const m = new three.Mesh(new three.IcosahedronGeometry(r, o.flat ? 1 : 3), mat(three, color, o));
  m.position.set(...pos);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export type BuildFn = (three: typeof THREE, group: THREE.Group) => ((t: number) => void) | void;

export interface StageProps {
  build: BuildFn;
  height?: number;
  background?: string;
  autoRotate?: boolean;
  distance?: number;
  targetY?: number;
  /** show the grass ground disc (turn off for water / terrain scenes) */
  ground?: boolean;
}

export function Stage({
  build,
  height = 340,
  background = '#9ec7d8',
  autoRotate = true,
  distance = 8,
  targetY = 0.7,
  ground = true,
}: StageProps) {
  const ref = useRef<HTMLDivElement>(null);
  const buildRef = useRef(build);
  buildRef.current = build;
  const [isNight, setIsNight] = useState(night);
  const nightRef = useRef(isNight);
  nightRef.current = isNight;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let w = el.clientWidth || 480;
    const h = height;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(w, h);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    el.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(background);
    scene.fog = new THREE.Fog(new THREE.Color(background).getHex(), distance * 2.2, distance * 4.5);

    const camera = new THREE.PerspectiveCamera(34, w / h, 0.1, 200);
    const target = new THREE.Vector3(0, targetY, 0);

    const hemi = new THREE.HemisphereLight(0xdff0ff, 0x6b7a55, 0.62);
    scene.add(hemi);
    const sun = new THREE.DirectionalLight(0xfff0d6, 1.15);
    sun.position.set(6, 11, 5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    const s = 7;
    sun.shadow.camera.left = -s;
    sun.shadow.camera.right = s;
    sun.shadow.camera.top = s;
    sun.shadow.camera.bottom = -s;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 40;
    sun.shadow.bias = -0.0004;
    scene.add(sun);

    // night rig: two warm park floodlights + a cool moon fill (intensity lerped in the loop)
    const floods: THREE.PointLight[] = [];
    [
      [3.2, 3.4, 2.2],
      [-3.2, 3.4, -2.2],
    ].forEach(([x, y, z]) => {
      const fl = new THREE.PointLight(0xffb45e, 0, 18, 1.8);
      fl.position.set(x, y, z);
      scene.add(fl);
      floods.push(fl);
    });
    const dayBg = new THREE.Color(background);
    const nightBg = new THREE.Color(0x0e1728);
    const daySun = new THREE.Color(0xfff0d6);
    const moonCol = new THREE.Color(0xa9c4ff);
    const dayHemiSky = new THREE.Color(0xdff0ff);
    const nightHemiSky = new THREE.Color(0x24365e);
    const dayHemiGnd = new THREE.Color(0x6b7a55);
    const nightHemiGnd = new THREE.Color(0x141c14);
    const bgNow = new THREE.Color(background);
    let nightK = nightRef.current ? 1 : 0;

    // textured grass ground (optional — off for water / terrain scenes)
    if (ground) {
      const groundMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
      groundMat.map = getTex(THREE, 'grass', 0x6f9e54, 24, 24);
      const groundMesh = new THREE.Mesh(new THREE.CircleGeometry(distance * 1.6, 64), groundMat);
      groundMesh.rotation.x = -Math.PI / 2;
      groundMesh.position.y = -0.02;
      groundMesh.receiveShadow = true;
      scene.add(groundMesh);
    }

    const group = new THREE.Group();
    scene.add(group);
    const update = buildRef.current(THREE, group) || undefined;

    let az = Math.PI * 0.25;
    let el2 = Math.PI * 0.28;
    let dragging = false;
    let px = 0;
    let py = 0;
    const applyCam = () => {
      const r = distance;
      camera.position.set(
        target.x + r * Math.cos(el2) * Math.sin(az),
        target.y + r * Math.sin(el2),
        target.z + r * Math.cos(el2) * Math.cos(az),
      );
      camera.lookAt(target);
    };
    const dom = renderer.domElement;
    dom.style.cursor = 'grab';
    const down = (e: PointerEvent) => {
      dragging = true;
      px = e.clientX;
      py = e.clientY;
      dom.style.cursor = 'grabbing';
      dom.setPointerCapture(e.pointerId);
    };
    const move = (e: PointerEvent) => {
      if (!dragging) return;
      az -= (e.clientX - px) * 0.01;
      el2 = Math.max(0.08, Math.min(1.45, el2 + (e.clientY - py) * 0.01));
      px = e.clientX;
      py = e.clientY;
    };
    const up = (e: PointerEvent) => {
      dragging = false;
      dom.style.cursor = 'grab';
      try {
        dom.releasePointerCapture(e.pointerId);
      } catch {
        /* noop */
      }
    };
    dom.addEventListener('pointerdown', down);
    dom.addEventListener('pointermove', move);
    dom.addEventListener('pointerup', up);

    const clock = new THREE.Clock();
    let raf = 0;
    const loop = () => {
      const t = clock.getElapsedTime();
      if (autoRotate && !dragging) az += 0.0045;
      applyCam();
      if (update) update(t);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    loop();

    const ro = new ResizeObserver(() => {
      w = el.clientWidth || w;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    });
    ro.observe(el);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      dom.removeEventListener('pointerdown', down);
      dom.removeEventListener('pointermove', move);
      dom.removeEventListener('pointerup', up);
      renderer.dispose();
      scene.traverse((obj) => {
        const anyObj = obj as unknown as {
          geometry?: THREE.BufferGeometry;
          material?: THREE.Material | THREE.Material[];
        };
        anyObj.geometry?.dispose?.();
        const m = anyObj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose());
        else m?.dispose?.();
      });
      if (dom.parentNode === el) el.removeChild(dom);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      <div ref={ref} style={{ width: '100%', height, borderRadius: 12, overflow: 'hidden' }} />
      <button
        onClick={() => setIsNight((n) => !n)}
        style={{
          position: 'absolute',
          top: 10,
          right: 10,
          padding: '4px 12px',
          borderRadius: 999,
          border: 'none',
          cursor: 'pointer',
          fontSize: 13,
          fontWeight: 700,
          color: isNight ? '#0e1728' : '#fff7e0',
          background: isNight ? '#ffd97a' : '#1f2b47',
          boxShadow: '0 1px 4px rgba(0,0,0,0.35)',
        }}
      >
        {isNight ? '☀ Day' : '🌙 Night'}
      </button>
    </div>
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, ball } from '../Stage';

// Shared peep builder — used by the Guest crowd and seated in rides. Supports
// varied skin tones, hair, shirt/trousers colours and facial EXPRESSIONS
// (happy / neutral / sad / surprised). Limbs pivot for a walk cycle or sit.
export type Expression = 'happy' | 'neutral' | 'sad' | 'surprised';
export interface PeepOpts {
  shirt?: number;
  trousers?: number;
  skin?: number;
  hair?: number;
  expression?: Expression;
  seated?: boolean;
}
export const SKIN_TONES = [0xf1c9a5, 0xe0a878, 0xc68642, 0x8d5524, 0x5c3a21];
export const SHIRTS = [0xc21a1a, 0x2f6fd0, 0x2e9e54, 0xe0a020, 0x8e44ad, 0xe06010, 0x18a0a0, 0xe060a0];
export const TROUSERS = [0x26305e, 0x3a2a1a, 0x333940, 0x5a3d22, 0x6a1030];
export const HAIRS = [0x4a3018, 0x1c1c1c, 0x7a5230, 0xb08040, 0x9a9a9a];

export function buildPeep(t: typeof THREE, o: PeepOpts = {}) {
  const SKIN = o.skin ?? 0xe0a878;
  const HAIR = o.hair ?? 0x4a3018;
  const SHIRT = o.shirt ?? 0xc21a1a;
  const TROU = o.trousers ?? 0x26305e;
  const SHOE = 0x2a1c10;
  const DARK = 0x1a1207;
  const expr = o.expression ?? 'happy';

  const grp = new t.Group();
  grp.add(box(t, [0.26, 0.14, 0.18], TROU, [0, 0.52, 0], { tex: 'fabric', repeat: [2, 1], rough: 0.9 }));
  grp.add(box(t, [0.3, 0.32, 0.2], SHIRT, [0, 0.74, 0], { tex: 'fabric', repeat: [2, 2], rough: 0.85 }));

  const head = new t.Group();
  head.position.set(0, 0.99, 0);
  head.add(ball(t, 0.12, SKIN, [0, 0, 0], { rough: 0.7 }));
  const hair = ball(t, 0.128, HAIR, [0, 0.04, -0.012], { rough: 0.9 });
  hair.scale.set(1.02, 0.72, 1.02);
  head.add(hair);

  const eyeR = expr === 'surprised' ? 0.034 : 0.028;
  const pupilR = expr === 'surprised' ? 0.019 : 0.017;
  [-0.048, 0.048].forEach((ex) => {
    const white = ball(t, eyeR, 0xffffff, [ex, 0.02, 0.098], { rough: 0.35 });
    white.scale.z = 0.6; // flatten into the face so the pupil sits proud of it
    head.add(white);
    head.add(ball(t, pupilR, 0x14141a, [ex, 0.02, 0.118], { rough: 0.25 })); // pupil, clearly outside the white
    const browTilt = expr === 'sad' ? (ex > 0 ? 0.35 : -0.35) : ex > 0 ? -0.15 : 0.15;
    head.add(box(t, [0.055, 0.014, 0.012], 0x2a1c10, [ex, expr === 'sad' ? 0.052 : 0.065, 0.112], { rotZ: browTilt })); // always-dark brow
  });

  // mouth by expression
  if (expr === 'surprised') {
    head.add(ball(t, 0.028, DARK, [0, -0.04, 0.108], { rough: 0.5 }));
  } else if (expr === 'neutral') {
    head.add(box(t, [0.06, 0.012, 0.012], DARK, [0, -0.045, 0.11]));
  } else {
    const m = new t.Mesh(new t.TorusGeometry(0.035, 0.008, 8, 12, Math.PI), new t.MeshStandardMaterial({ color: DARK, roughness: 0.5 }));
    m.rotation.set(expr === 'sad' ? 0 : Math.PI, 0, 0);
    m.position.set(0, expr === 'sad' ? -0.06 : -0.035, 0.108);
    head.add(m);
  }
  head.add(ball(t, 0.018, SKIN, [0, -0.005, 0.12], { rough: 0.6 })); // nose
  grp.add(head);

  const limb = (px: number, py: number, col: number, len: number, hand?: number, texd?: boolean) => {
    const pivot = new t.Group();
    pivot.position.set(px, py, 0);
    pivot.add(box(t, [0.09, len, 0.11], col, [0, -len / 2, 0], texd ? { tex: 'fabric', repeat: [1, 2], rough: 0.85 } : { rough: 0.7 }));
    if (hand != null) pivot.add(ball(t, 0.05, hand, [0, -len, 0], { rough: 0.7 }));
    grp.add(pivot);
    return pivot;
  };
  const armL = limb(-0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const armR = limb(0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const legL = limb(-0.08, 0.46, TROU, 0.4, undefined, true);
  const legR = limb(0.08, 0.46, TROU, 0.4, undefined, true);
  legL.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));
  legR.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));

  if (o.seated) {
    legL.rotation.x = -1.5;
    legR.rotation.x = -1.5;
    armL.rotation.x = -1.1;
    armR.rotation.x = -1.1;
    if (expr === 'surprised') {
      armL.rotation.x = -2.6; // arms up!
      armR.rotation.x = -2.6;
    }
  }

  const walk = (time: number, phase = 0) => {
    const s = Math.sin(time * 5 + phase);
    legL.rotation.x = s * 0.5;
    legR.rotation.x = -s * 0.5;
    armL.rotation.x = -s * 0.45;
    armR.rotation.x = s * 0.45;
    grp.position.y = Math.abs(Math.cos(time * 5 + phase)) * 0.03;
  };
  return { group: grp, walk, head };
}

// A diverse crowd of walking guests — varied skin tones, outfits and moods.
export function Guest() {
  return (
    <Stage
      distance={5.2}
      targetY={0.6}
      autoRotate
      build={(t, g) => {
        const exprs: Expression[] = ['happy', 'neutral', 'surprised', 'happy', 'sad'];
        const peeps = exprs.map((expression, i) => {
          const p = buildPeep(t, {
            skin: SKIN_TONES[i % SKIN_TONES.length],
            hair: HAIRS[i % HAIRS.length],
            shirt: SHIRTS[i % SHIRTS.length],
            trousers: TROUSERS[i % TROUSERS.length],
            expression,
          });
          p.group.position.set((i - 2) * 0.85, 0, (i % 2) * 0.4 - 0.2);
          p.group.rotation.y = 0.3;
          g.add(p.group);
          return p;
        });
        return (time) => peeps.forEach((p, i) => p.walk(time, i * 1.3));
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, cyl } from '../Stage';

// Detailed animated water via a custom GLSL ShaderMaterial, tuned to RCT2's
// bright park water. Six directional wave octaves displace the mesh; the
// fragment stage adds high-frequency procedural ripple normals, crest foam,
// an edge foam ring near the shore (uRadius), depth colour gradient, Fresnel
// rim, sun specular and glints. `radius` clips to a round pool; pass a huge
// radius for a square sheet (TerrainMap).
export function buildWater(t: typeof THREE, size = 4, seg = 140, radius = 1e6) {
  const geo = new t.PlaneGeometry(size, size, seg, seg);
  const mat = new t.ShaderMaterial({
    transparent: true,
    depthWrite: true,
    uniforms: {
      uTime: { value: 0 },
      uRadius: { value: radius },
      uShallow: { value: new t.Color(0x63d0e8) },
      uMid: { value: new t.Color(0x2286c8) },
      uDeep: { value: new t.Color(0x0c3a70) },
      uSun: { value: new t.Vector3(6, 11, 5).normalize() },
    },
    vertexShader: [
      'uniform float uTime;',
      'varying float vH;',
      'varying vec3 vWorld;',
      'varying vec2 vLocal;',
      'float wave(vec2 p, vec2 dir, float freq, float speed, float amp, float tme) {',
      '  return sin(dot(p, dir) * freq + tme * speed) * amp;',
      '}',
      'void main() {',
      '  vLocal = position.xy;',
      '  vec3 p = position;',
      '  float tme = uTime;',
      '  float w = 0.0;',
      '  w += wave(p.xy, vec2(1.0, 0.2), 1.1, 1.3, 0.10, tme);',
      '  w += wave(p.xy, vec2(-0.4, 1.0), 1.7, 1.7, 0.07, tme);',
      '  w += wave(p.xy, vec2(0.8, 0.8), 0.8, 1.05, 0.065, tme);',
      '  w += wave(p.xy, vec2(-0.9, 0.5), 2.3, 2.1, 0.035, tme);',
      '  w += wave(p.xy, vec2(0.3, -1.0), 3.1, 2.6, 0.022, tme);',
      '  w += wave(p.xy, vec2(-0.7, -0.7), 4.3, 3.2, 0.012, tme);',
      '  p.z += w;',
      '  vH = w;',
      '  vec4 wp = modelMatrix * vec4(p, 1.0);',
      '  vWorld = wp.xyz;',
      '  gl_Position = projectionMatrix * viewMatrix * wp;',
      '}',
    ].join('\n'),
    fragmentShader: [
      'precision highp float;',
      'uniform float uTime;',
      'uniform float uRadius;',
      'uniform vec3 uShallow;',
      'uniform vec3 uMid;',
      'uniform vec3 uDeep;',
      'uniform vec3 uSun;',
      'varying float vH;',
      'varying vec3 vWorld;',
      'varying vec2 vLocal;',
      'float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }',
      'void main() {',
      '  float r = length(vLocal);',
      '  if (r > uRadius) discard;',
      '  vec3 n = normalize(cross(dFdx(vWorld), dFdy(vWorld)));',
      // high-frequency procedural ripple detail layered onto the geometric normal
      '  float rip = sin(vWorld.x * 34.0 + uTime * 3.1) * sin(vWorld.z * 29.0 - uTime * 2.6)',
      '            + 0.6 * sin(vWorld.x * 61.0 - uTime * 4.4) * sin(vWorld.z * 53.0 + uTime * 3.7);',
      '  n = normalize(n + vec3(dFdx(rip), 0.0, dFdy(rip)) * 6.0);',
      '  vec3 v = normalize(cameraPosition - vWorld);',
      '  float fres = pow(1.0 - max(dot(n, v), 0.0), 3.0);',
      // three-stop depth gradient driven by wave height
      '  float hMix = clamp(vH * 3.2 + 0.5, 0.0, 1.0);',
      '  vec3 base = hMix < 0.5 ? mix(uDeep, uMid, hMix * 2.0) : mix(uMid, uShallow, hMix * 2.0 - 1.0);',
      '  vec3 l = normalize(uSun);',
      '  vec3 hf = normalize(l + v);',
      '  float spec = pow(max(dot(n, hf), 0.0), 42.0);',
      '  float diff = max(dot(n, l), 0.0) * 0.25 + 0.75;',
      '  vec3 col = base * diff + vec3(1.0) * spec * 0.22 + fres * vec3(0.55, 0.78, 1.0) * 0.16;',
      // crest foam: bright broken streaks on the highest wave tops
      '  float crest = smoothstep(0.16, 0.24, vH);',
      '  float streak = hash(floor(vWorld.xz * 14.0) + floor(uTime * 2.0));',
      '  col = mix(col, vec3(0.9, 0.95, 0.98), crest * streak * 0.45);',
      // shore foam ring hugging the pool edge (only when a real radius is set)
      '  if (uRadius < 1000.0) {',
      '    float shore = smoothstep(uRadius - 0.22, uRadius - 0.03, r);',
      '    float lap = 0.5 + 0.5 * sin(r * 26.0 - uTime * 2.4 + rip * 2.0);',
      '    col = mix(col, vec3(0.94, 0.98, 1.0), shore * (0.45 + 0.45 * lap));',
      '  }',
      // sun glints
      '  float sp = sin(vWorld.x * 24.0 + uTime * 6.0) * sin(vWorld.z * 24.0 - uTime * 5.0);',
      '  col += smoothstep(0.96, 1.0, sp) * 0.1;',
      '  gl_FragColor = vec4(col, 0.95);',
      '}',
    ].join('\n'),
  });
  const mesh = new t.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  return { mesh, update: (time: number) => (mat.uniforms.uTime.value = time) };
}

export function WaterTile() {
  return (
    <Stage
      distance={5}
      targetY={0.2}
      background="#bfe6f2"
      ground={false}
      build={(t, g) => {
        // opaque sand basin + dark pool floor + beach rim so nothing shows through
        g.add(cyl(t, 2.5, 2.7, 0.7, 0xcdb98a, [0, -0.35, 0], { tex: 'sand', repeat: [10, 2], rough: 1, seg: 48 }));
        g.add(cyl(t, 2.35, 2.35, 0.1, 0x0c3a70, [0, 0.02, 0], { rough: 0.35, seg: 48 }));
        g.add(cyl(t, 2.55, 2.7, 0.18, 0x9a8a5f, [0, 0.06, 0], { tex: 'sand', repeat: [12, 1], rough: 1, seg: 48 }));
        const water = buildWater(t, 4.8, 140, 2.32);
        water.mesh.position.y = 0.16;
        g.add(water.mesh);
        return (time) => water.update(time);
      }}
