}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, mat } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Go-karts matched to the RCT2 KART1 sprite: an ORANGE kart fleet with white-
// helmeted drivers racing a FLAT asphalt ring circuit with red/white kerbs, a
// chequered start line, a start gantry and tyre-stack corners. (The previous
// version used a fat torus for the track which buried the karts inside it.)
export function GoKarts() {
  return (
    <Stage
      distance={7}
      targetY={0.3}
      build={(t, g) => {
        const R = 2.2; // racing line radius
        const IN = 1.45;
        const OUT = 2.95;

        // flat asphalt ring just above the grass
        const track = new t.Mesh(new t.RingGeometry(IN, OUT, 64), mat(t, 0x4a4d52, { tex: 'asphalt', repeat: [10, 10], rough: 0.96, bump: 0.02 }));
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.02;
        track.receiveShadow = true;
        g.add(track);
        // infield grass disc so the ring edge reads
        g.add(cyl(t, IN - 0.04, IN - 0.04, 0.03, 0x6f9e54, [0, 0.02, 0], { tex: 'grass', repeat: [6, 6], rough: 1, seg: 40 }));

        // red/white kerb blocks around inner + outer edges
        const kerb = (radius: number, n: number) => {
          for (let i = 0; i < n; i++) {
            const a = (i / n) * Math.PI * 2;
            g.add(
              box(t, [0.16, 0.05, (2 * Math.PI * radius) / n - 0.03], i % 2 ? 0xdd3838 : 0xf0f0f0, [Math.cos(a) * radius, 0.045, Math.sin(a) * radius], {
                rough: 0.6,
                rotY: -a,
              }),
            );
          }
        };
        kerb(IN + 0.08, 36);
        kerb(OUT - 0.08, 48);

        // chequered start/finish line across the track
        for (let row = 0; row < 2; row++)
          for (let k = 0; k < 6; k++) {
            const rr = IN + 0.25 + k * 0.25;
            g.add(box(t, [0.14, 0.022, 0.25], (k + row) % 2 ? 0x111114 : 0xf5f5f5, [rr, 0.05, (row - 0.5) * 0.15], { rough: 0.6 }));
          }
        // start gantry: posts + red beam over the track
        [IN - 0.05, OUT + 0.05].forEach((rr) => g.add(cyl(t, 0.04, 0.04, 0.9, 0x8a8f98, [rr, 0.45, 0], { tex: 'metal', metal: 0.5, rough: 0.4, seg: 10 })));
        g.add(box(t, [OUT - IN + 0.3, 0.08, 0.12], 0xdd3838, [(IN + OUT) / 2, 0.9, 0], { rough: 0.55 }));

        // tyre stacks at four corners outside the track
        for (let c = 0; c < 4; c++) {
          const a = (c / 4) * Math.PI * 2 + Math.PI / 4;
          for (let s = 0; s < 2; s++)
            g.add(cyl(t, 0.11, 0.11, 0.09, 0x18181c, [Math.cos(a) * (OUT + 0.3), 0.05 + s * 0.09, Math.sin(a) * (OUT + 0.3)], { rough: 0.9, seg: 14 }));
        }

        // orange kart fleet with white-helmeted drivers
        const cols = [0xe8641c, 0xf08a30, 0xe8641c, 0xd6541a];
        const karts: THREE.Group[] = [];
        for (let i = 0; i < 4; i++) {
          const k = new t.Group();
          k.add(box(t, [0.36, 0.1, 0.7], 0x141417, [0, 0.14, 0], { tex: 'metal', metal: 0.5, rough: 0.5 })); // chassis
          k.add(box(t, [0.38, 0.18, 0.44], cols[i], [0, 0.26, -0.02], { tex: 'plastic', rough: 0.35 })); // body
          k.add(box(t, [0.5, 0.05, 0.14], cols[i], [0, 0.2, 0.34], { tex: 'plastic', rough: 0.35 })); // front wing
          k.add(box(t, [0.44, 0.05, 0.12], cols[i], [0, 0.3, -0.36], { tex: 'plastic', rough: 0.35 })); // rear wing
          k.add(box(t, [0.24, 0.14, 0.24], 0x101014, [0, 0.34, -0.14], { rough: 0.8 })); // seat shell
          k.add(cyl(t, 0.07, 0.07, 0.03, 0x1a1a1e, [0, 0.4, 0.16], { rotX: 1.1, seg: 12 })); // steering wheel
          // chunky wheels OUTSIDE the body so they read
          [
            [-0.24, 0.26],
            [0.24, 0.26],
            [-0.26, -0.26],
            [0.26, -0.26],
          ].forEach(([x, z]) => k.add(cyl(t, 0.11, 0.11, 0.1, 0x101013, [x, 0.11, z], { rotZ: Math.PI / 2, tex: 'metal', metal: 0.3, rough: 0.6, seg: 14 })));
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i], seated: true });
          p.group.scale.setScalar(0.4);
          p.group.position.set(0, 0.18, -0.12);
          k.add(p.group);
          k.add(cyl(t, 0.09, 0.095, 0.11, 0xf0f0f4, [0, 0.58, -0.1], { rough: 0.3, seg: 14 })); // white helmet
          k.scale.setScalar(1.15);
          g.add(k);
          karts.push(k);
        }
        return (time) => {
          karts.forEach((k, i) => {
            const a = time * (0.65 + i * 0.06) + (i / 4) * Math.PI * 2;
            const rr = R + Math.sin(time * 0.8 + i * 2) * 0.35; // weave between lanes
            k.position.set(Math.cos(a) * rr, 0.02, Math.sin(a) * rr);
            k.rotation.y = -a; // face along travel direction
            k.rotation.z = Math.sin(time * 3 + i) * 0.02;
          });
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Chair swing / wave-swinger, rebuilt: chairs hang from the CANOPY RIM on two
// visible chains, each hanger pivots at the rim and flings outward as the top
// spins (tilt follows spin speed). Striped red/gold carnival canopy, mirrored
// centre column, and a ring of lamps around the rim that glow at night.
export function SwingRide() {
  return (
    <Stage
      distance={7.5}
      targetY={1.8}
      build={(t, g) => {
        const H = 3.2;
        const RIM = 1.25;
        const CHAIN = 0.95;
        const RED = 0xc23434;
        const GOLD = 0xd8b040;

        // base + column
        g.add(cyl(t, 0.6, 0.72, 0.35, 0x8a8f98, [0, 0.17, 0], { tex: 'concrete', repeat: [6, 1], rough: 0.9, seg: 24 }));
        g.add(cyl(t, 0.55, 0.55, 0.06, RED, [0, 0.38, 0], { rough: 0.6, seg: 24 }));
        g.add(cyl(t, 0.17, 0.22, H, RED, [0, H / 2 + 0.3, 0], { tex: 'plastic', repeat: [6, 3], rough: 0.5, seg: 18 }));
        // mirrored panels up the column
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          g.add(box(t, [0.09, 1.2, 0.02], 0xe8e8f0, [Math.cos(a) * 0.19, 1.6, Math.sin(a) * 0.19], { metal: 0.8, rough: 0.15, rotY: -a }));
        }

        const top = new t.Group();
        top.position.y = H + 0.3;
        g.add(top);
        // striped conical canopy (red/gold wedges) + rim ring + finial
        const SEGS = 12;
        for (let i = 0; i < SEGS; i++) {
          const a0 = (i / SEGS) * Math.PI * 2;
          const wedge = new t.Mesh(
            new t.CylinderGeometry(0.03, RIM, 0.45, 3, 1, false, a0, (Math.PI * 2) / SEGS),
            new t.MeshStandardMaterial({ color: i % 2 ? RED : GOLD, roughness: 0.55 }),
          );
          wedge.position.y = 0.36;
          wedge.castShadow = true;
          top.add(wedge);
        }
        top.add(cyl(t, RIM + 0.04, RIM + 0.04, 0.1, RED, [0, 0.12, 0], { rough: 0.55, seg: 28 }));
        top.add(ball(t, 0.1, GOLD, [0, 0.66, 0], { metal: 0.6, rough: 0.3 }));
        // rim lamps (emissive — pop at night)
        const lampMats: THREE.MeshStandardMaterial[] = [];
        for (let i = 0; i < 12; i++) {
          const a = (i / 12) * Math.PI * 2;
          const m = new t.MeshStandardMaterial({ color: 0xfff3c0, emissive: 0xffcc55, emissiveIntensity: 0.9, roughness: 0.4 });
          const lamp = new t.Mesh(new t.SphereGeometry(0.045, 10, 8), m);
          lamp.position.set(Math.cos(a) * (RIM + 0.04), 0.06, Math.sin(a) * (RIM + 0.04));
          top.add(lamp);
          lampMats.push(m);
        }

        // hangers: pivot AT the rim; two chains run down to the chair
        const N = 8;
        const hangers: THREE.Group[] = [];
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          const hanger = new t.Group();
          hanger.position.set(Math.cos(a) * RIM, 0.08, Math.sin(a) * RIM);
          hanger.rotation.y = -a; // local +x points radially outward
          top.add(hanger);
          [-0.09, 0.09].forEach((zz) =>
            hanger.add(cyl(t, 0.012, 0.012, CHAIN, 0xb9bec6, [0, -CHAIN / 2, zz], { tex: 'metal', metal: 0.7, rough: 0.35, seg: 6 })),
          );
          const chair = new t.Group();
          chair.position.y = -CHAIN;
          hanger.add(chair);
          chair.add(box(t, [0.3, 0.05, 0.3], 0x2f6fd0, [0, 0, 0], { tex: 'plastic', rough: 0.4 })); // seat pan
          chair.add(box(t, [0.05, 0.32, 0.3], 0x2f6fd0, [-0.14, 0.16, 0], { tex: 'plastic', rough: 0.4 })); // back (inboard side)
          chair.add(box(t, [0.28, 0.035, 0.035], GOLD, [0, 0.16, 0.16], { metal: 0.5, rough: 0.35 })); // safety chain bar
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.set(0.02, -0.17, 0);
          p.group.rotation.y = Math.PI / 2; // face direction of travel
          chair.add(p.group);
          hangers.push(hanger);
        }
        return (time) => {
          const speed = 0.9;
          top.rotation.y = time * speed;
          const fling = 0.5; // outward tilt from spin
          hangers.forEach((h, i) => {
            h.rotation.z = -fling - Math.sin(time * 1.6 + i) * 0.05; // swing out + gentle flutter
          });
          lampMats.forEach((m, i) => (m.emissiveIntensity = 0.75 + Math.sin(time * 6 + i) * 0.25));
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';

// Desert sand tile matched to the RCT2 sand terrain: a bevelled sand slab with
// soft dune mounds, rows of wind ripples that follow the dune curves, sun-
// bleached rocks, a saguaro cactus and a bleached steer skull for character.
export function SandTile() {
  return (
    <Stage
      distance={4.6}
      targetY={0.35}
      background="#d8ecf4"
      build={(t, g) => {
        const SAND = 0xd9c48f;
        const SAND_D = 0xb59b63;
        const SAND_L = 0xe8d6a4;

        // slab + soil rim
        g.add(box(t, [2.2, 0.26, 2.2], SAND, [0, 0.13, 0], { tex: 'sand', repeat: [4, 4], rough: 1, bump: 0.04 }));
        g.add(box(t, [2.24, 0.14, 2.24], SAND_D, [0, -0.01, 0], { tex: 'sand', repeat: [5, 1], rough: 1 }));

        // soft dune mounds (squashed, sand-textured spheres)
        const dune = (x: number, z: number, r: number, h: number, col: number) => {
          const d = ball(t, r, col, [x, 0.26, z], { tex: 'sand', repeat: [3, 2], rough: 1 });
          d.scale.set(1, h, 1);
          g.add(d);
        };
        dune(-0.45, -0.35, 0.75, 0.42, SAND_L);
        dune(0.55, 0.25, 0.6, 0.36, SAND);
        dune(0.15, -0.7, 0.45, 0.3, SAND_L);
        dune(-0.6, 0.6, 0.4, 0.28, SAND);

        // wind ripples: thin crescents sweeping across the tile
        for (let row = 0; row < 7; row++) {
          const z0 = -0.9 + row * 0.3;
          for (let k = 0; k < 4; k++) {
            const x0 = -0.85 + k * 0.5 + (row % 2) * 0.22;
            g.add(
              box(t, [0.4, 0.018, 0.05], SAND_D, [x0, 0.27 + Math.sin(row + k) * 0.02, z0], {
                rough: 1,
                rotY: 0.35 + Math.sin(row * 1.7 + k) * 0.25,
              }),
            );
          }
        }

        // sun-bleached rocks
        [
          [-0.85, 0.8, 0.11],
          [0.9, -0.75, 0.09],
          [0.8, 0.85, 0.07],
        ].forEach(([x, z, r]) => g.add(ball(t, r as number, 0xa89f8c, [x as number, 0.3, z as number], { tex: 'concrete', repeat: [2, 2], flat: true, rough: 1 })));

        // saguaro cactus: trunk + two elbow arms
        const CAC = 0x4c7a3a;
        g.add(cyl(t, 0.09, 0.11, 0.85, CAC, [-0.75, 0.68, -0.65], { tex: 'leaf', repeat: [2, 3], rough: 0.9, seg: 10 }));
        g.add(cyl(t, 0.055, 0.06, 0.3, CAC, [-0.93, 0.72, -0.65], { tex: 'leaf', rough: 0.9, seg: 8, rotZ: Math.PI / 2 }));
        g.add(cyl(t, 0.055, 0.06, 0.34, CAC, [-1.05, 0.92, -0.65], { tex: 'leaf', rough: 0.9, seg: 8 }));
        g.add(cyl(t, 0.05, 0.055, 0.24, CAC, [-0.58, 0.78, -0.65], { tex: 'leaf', rough: 0.9, seg: 8, rotZ: -Math.PI / 2 }));
        g.add(cyl(t, 0.05, 0.055, 0.26, CAC, [-0.48, 0.95, -0.65], { tex: 'leaf', rough: 0.9, seg: 8 }));

        // bleached steer skull half-buried in the sand
        g.add(ball(t, 0.09, 0xe8e2d2, [0.55, 0.28, -0.5], { flat: true, rough: 0.8 }));
        g.add(box(t, [0.07, 0.04, 0.06], 0xe8e2d2, [0.55, 0.24, -0.42], { rough: 0.8 })); // muzzle
        [-1, 1].forEach((s) =>
          g.add(cyl(t, 0.012, 0.02, 0.16, 0xdcd4c0, [0.55 + s * 0.11, 0.34, -0.52], { rough: 0.8, seg: 6, rotZ: s * 1.2 })),
        );
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';

// Haunted house matched to the RCT2 HHBUILD sprite: a grand THREE-TIER mansion
// — a wide ground floor with a wraparound slate awning roof, a narrower middle
// storey, and a square clock tower with a steep pyramidal cap. Cream/timber
// walls, blue-slate shingled roofs edged with mossy GREEN trim and green ball
// finials at every corner, rows of tall amber-lit windows that flicker, a
// round clock face, and vine-wrapped porch posts.
export function HauntedMansion() {
  return (
    <Stage
      distance={9}
      targetY={1.7}
      background="#5a6b86"
      build={(t, g) => {
        const WALL = 0xcfc0a0; // cream stone/timber (sprite #807060 lit)
        const TIMBER = 0x6a5a40;
        const SLATE = 0x5a707a; // roof shingles
        const SLATE_D = 0x435459;
        const MOSS = 0x4c6e30; // green trim (sprite #305020)
        const wins: THREE.MeshStandardMaterial[] = [];
        const winPane = (w: number, h: number) => {
          const m = new t.MeshStandardMaterial({ color: 0x3a2a10, emissive: 0xdf9a30, emissiveIntensity: 0.8, roughness: 0.5 });
          wins.push(m);
          return new t.Mesh(new t.BoxGeometry(w, h, 0.05), m);
        };
        const finial = (x: number, y: number, z: number) => {
          g.add(cyl(t, 0.03, 0.05, 0.14, MOSS, [x, y, z], { rough: 0.8, seg: 8 }));
          g.add(ball(t, 0.09, MOSS, [x, y + 0.13, z], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.9 }));
        };

        // ---- tier 1: wide ground floor ----
        g.add(box(t, [2.6, 1.1, 2.2], WALL, [0, 0.55, 0], { tex: 'concrete', repeat: [8, 3], rough: 0.9 }));
        // timber corner posts + door
        [-1.28, 1.28].forEach((x) => [-1.08, 1.08].forEach((z) => g.add(box(t, [0.1, 1.1, 0.1], TIMBER, [x, 0.55, z], { tex: 'wood', repeat: [1, 3], rough: 0.9 }))));
        g.add(box(t, [0.44, 0.8, 0.06], 0x2a1c10, [0.5, 0.4, 1.12], { tex: 'wood', repeat: [2, 3], rough: 0.85 })); // door
        // ground-floor window rows (front + sides), amber lit
        for (const x of [-0.9, -0.4, 0.05]) {
          const wmesh = winPane(0.26, 0.55);
          wmesh.position.set(x, 0.6, 1.11);
          g.add(wmesh);
          g.add(box(t, [0.32, 0.62, 0.03], MOSS, [x, 0.6, 1.1], { rough: 0.85 })); // green surround
        }
        for (const z of [-0.6, 0, 0.6]) {
          const wmesh = winPane(0.26, 0.55);
          wmesh.rotation.y = Math.PI / 2;
          wmesh.position.set(1.31, 0.6, z);
          g.add(wmesh);
        }
        // wraparound slate awning roof over tier 1 (4 sloped skirts) + moss edge
        [
          [0, 0, 1.32, 0.62, 3.0, 0],
          [0, 0, -1.32, -0.62, 3.0, 0],
        ].forEach(([, , z, rot, w]) => {
          g.add(box(t, [w as number, 0.08, 0.66], SLATE, [0, 1.32, z as number], { tex: 'concrete', repeat: [8, 2], rough: 0.85, rotX: rot as number }));
        });
        [
          [1.46, 0.62],
          [-1.46, -0.62],
        ].forEach(([x, rot]) => {
          g.add(box(t, [0.66, 0.08, 2.6], SLATE, [x as number, 1.32, 0], { tex: 'concrete', repeat: [2, 8], rough: 0.85, rotZ: rot as number }));
        });
        [-1.6, 1.6].forEach((x) => [-1.5, 1.5].forEach((z) => g.add(box(t, [0.5, 0.06, 0.5], MOSS, [x * 0.95, 1.18, z * 0.95], { tex: 'leaf', repeat: [2, 2], rough: 0.95 }))));
        [-1.5, 1.5].forEach((x) => [-1.42, 1.42].forEach((z) => finial(x, 1.28, z)));

        // ---- tier 2: middle storey ----
        g.add(box(t, [1.7, 1.0, 1.4], WALL, [0, 1.95, 0], { tex: 'concrete', repeat: [6, 3], rough: 0.9 }));
        [-0.82, 0.82].forEach((x) => [-0.66, 0.66].forEach((z) => g.add(box(t, [0.09, 1.0, 0.09], TIMBER, [x, 1.95, z], { tex: 'wood', repeat: [1, 3], rough: 0.9 }))));
        for (const x of [-0.5, 0, 0.5]) {
          const wmesh = winPane(0.24, 0.5);
          wmesh.position.set(x, 2.0, 0.71);
          g.add(wmesh);
          g.add(box(t, [0.3, 0.56, 0.03], MOSS, [x, 2.0, 0.7], { rough: 0.85 }));
        }
        // tier-2 skirt roof + finials
        g.add(box(t, [2.1, 0.08, 0.5], SLATE, [0, 2.52, 0.82], { tex: 'concrete', repeat: [6, 1], rough: 0.85, rotX: 0.6 }));
        g.add(box(t, [2.1, 0.08, 0.5], SLATE, [0, 2.52, -0.82], { tex: 'concrete', repeat: [6, 1], rough: 0.85, rotX: -0.6 }));
        g.add(box(t, [0.5, 0.08, 1.75], SLATE, [0.95, 2.52, 0], { tex: 'concrete', repeat: [1, 6], rough: 0.85, rotZ: -0.6 }));
        g.add(box(t, [0.5, 0.08, 1.75], SLATE, [-0.95, 2.52, 0], { tex: 'concrete', repeat: [1, 6], rough: 0.85, rotZ: 0.6 }));
        [-0.95, 0.95].forEach((x) => [-0.78, 0.78].forEach((z) => finial(x, 2.6, z)));

        // ---- tier 3: clock tower ----
        g.add(box(t, [0.85, 1.0, 0.85], WALL, [0, 3.1, 0], { tex: 'concrete', repeat: [3, 3], rough: 0.9 }));
        [-0.4, 0.4].forEach((x) => [-0.4, 0.4].forEach((z) => g.add(box(t, [0.08, 1.0, 0.08], TIMBER, [x, 3.1, z], { tex: 'wood', repeat: [1, 3], rough: 0.9 }))));
        // round clock face + hands
        g.add(cyl(t, 0.2, 0.2, 0.05, 0xe8dfc8, [0, 3.25, 0.44], { rotX: Math.PI / 2, rough: 0.6, seg: 20 }));
        g.add(box(t, [0.02, 0.13, 0.02], 0x2a1c10, [0, 3.3, 0.47], { rough: 0.5 }));
        g.add(box(t, [0.1, 0.02, 0.02], 0x2a1c10, [0.04, 3.25, 0.47], { rough: 0.5 }));
        const tw = winPane(0.2, 0.4);
        tw.position.set(0, 2.95, 0.44);
        g.add(tw);
        // steep pyramidal slate cap + moss ridge + top finial
        g.add(cyl(t, 0.03, 0.68, 0.85, SLATE_D, [0, 4.0, 0], { seg: 4, rough: 0.85 }));
        g.add(cyl(t, 0.03, 0.7, 0.1, MOSS, [0, 3.63, 0], { seg: 4, rough: 0.9 }));
        finial(0, 4.42, 0);

        // porch deck + steps + railing
        g.add(box(t, [2.7, 0.1, 0.5], 0x7a6448, [0, 0.05, 1.36], { tex: 'wood', repeat: [8, 1], rough: 0.9 })); // deck
        g.add(box(t, [0.7, 0.07, 0.3], 0x6a5640, [0.5, 0.035, 1.72], { tex: 'wood', repeat: [3, 1], rough: 0.9 })); // step
        for (let px = -1.2; px <= 1.2; px += 0.4) {
          if (Math.abs(px - 0.5) < 0.35) continue; // gap at the door
          g.add(cyl(t, 0.025, 0.025, 0.32, TIMBER, [px, 0.26, 1.58], { tex: 'wood', rough: 0.9, seg: 6 }));
        }
        g.add(box(t, [2.6, 0.04, 0.04], TIMBER, [0, 0.43, 1.58], { tex: 'wood', repeat: [8, 1], rough: 0.9 })); // rail
        // crooked brick chimney
        g.add(box(t, [0.28, 1.3, 0.28], 0x7a4a3a, [0.85, 2.6, -0.5], { tex: 'concrete', repeat: [2, 5], rough: 0.95, rotZ: 0.05 }));
        g.add(box(t, [0.36, 0.12, 0.36], 0x5a352a, [0.9, 3.28, -0.5], { tex: 'concrete', rough: 0.95, rotZ: 0.05 }));
        // shutters beside ground-floor windows (middle one hangs askew)
        [-0.9, -0.4, 0.05].forEach((x, si) => {
          g.add(box(t, [0.09, 0.55, 0.02], 0x3c5228, [x - 0.21, 0.6, 1.115], { tex: 'wood', repeat: [1, 3], rough: 0.9, rotZ: si === 1 ? 0.28 : 0 }));
          g.add(box(t, [0.09, 0.55, 0.02], 0x3c5228, [x + 0.21, 0.6, 1.115], { tex: 'wood', repeat: [1, 3], rough: 0.9 }));
        });
        // rusty iron fence out front
        for (let fx = -1.5; fx <= 1.5; fx += 0.25) g.add(cyl(t, 0.014, 0.014, 0.42, 0x2c2c30, [fx, 0.21, 2.1], { metal: 0.5, rough: 0.6, seg: 6 }));
        [0.12, 0.36].forEach((fy) => g.add(box(t, [3.1, 0.03, 0.03], 0x2c2c30, [0, fy, 2.1], { metal: 0.5, rough: 0.6 })));
        // flickering door lantern
        const lam = new t.MeshStandardMaterial({ color: 0xffe3a0, emissive: 0xffaa22, emissiveIntensity: 1, roughness: 0.4 });
        const lantern = new t.Mesh(new t.BoxGeometry(0.1, 0.14, 0.1), lam);
        lantern.position.set(0.85, 0.95, 1.14);
        g.add(lantern);
        wins.push(lam);
        // low ground fog
        const fogDisc = new t.Mesh(new t.CircleGeometry(2.6, 32), new t.MeshStandardMaterial({ color: 0xaebacf, transparent: true, opacity: 0.16, roughness: 1 }));
        fogDisc.rotation.x = -Math.PI / 2;
        fogDisc.position.y = 0.12;
        g.add(fogDisc);
        // circling bats
        const bats: THREE.Group[] = [];
        for (let b = 0; b < 3; b++) {
          const bat = new t.Group();
          bat.add(box(t, [0.05, 0.03, 0.03], 0x14141a, [0, 0, 0]));
          bat.add(box(t, [0.1, 0.015, 0.05], 0x14141a, [-0.07, 0.01, 0], { rotZ: 0.4 }));
          bat.add(box(t, [0.1, 0.015, 0.05], 0x14141a, [0.07, 0.01, 0], { rotZ: -0.4 }));
          g.add(bat);
          bats.push(bat);
        }
        // vine-wrapped porch posts + creeping moss patches on walls
        [-1.28, 1.28].forEach((x) => g.add(cyl(t, 0.045, 0.045, 1.05, MOSS, [x, 0.55, 1.2], { tex: 'leaf', repeat: [1, 4], rough: 0.95, seg: 8 })));
        [
          [-1.1, 0.9, 1.11],
          [0.9, 1.5, 1.11],
          [1.31, 1.9, 0.4],
        ].forEach(([x, y, z]) => g.add(ball(t, 0.16, MOSS, [x, y, z], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.95 })));

        return (time) => {
          wins.forEach((m, i) => (m.emissiveIntensity = 0.5 + Math.abs(Math.sin(time * 2.6 + i * 1.9)) * 0.65));
          bats.forEach((bat, b) => {
            const a = time * (0.9 + b * 0.25) + b * 2.1;
            bat.position.set(Math.cos(a) * (1.4 + b * 0.35), 3.4 + Math.sin(time * 3 + b) * 0.25, Math.sin(a) * (1.4 + b * 0.35));
            bat.rotation.y = -a + Math.PI / 2;
            bat.rotation.z = Math.sin(time * 14 + b) * 0.5;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Swinging ship matched to the RCT2 SWSH1 sprite: an ORANGE A-frame (two legs
// per side meeting at a high pivot), a dark slate cross-beam and centre pole,
// and a MAGENTA hull with carved dragon heads at BOTH ends, orange gunwale
// trim and rows of orange/pink striped seat backs. Riders swing with it.
export function PirateShip() {
  return (
    <Stage
      distance={8.5}
      targetY={1.7}
      build={(t, g) => {
        const pivotY = 3.1;
        const ORANGE = 0xe8641c; // frame (sprite #e05020)
        const WOOD = 0x8a5a28; // natural wooden hull
        const WOOD_D = 0x5a3a1c; // hull shadow planking
        const SLATE = 0x2e4444; // beam/pole (sprite #203030)

        // orange A-frame: two legs each side, meeting at the pivot
        [-1, 1].forEach((zs) => {
          const z = zs * 0.7;
          [-1, 1].forEach((xs) => {
            const x0 = xs * 1.6;
            const L = Math.hypot(x0, pivotY);
            const ang = Math.atan2(pivotY, -x0) - Math.PI / 2;
            g.add(box(t, [0.13, L, 0.13], ORANGE, [x0 / 2, pivotY / 2, z], { tex: 'metal', repeat: [1, 7], metal: 0.3, rough: 0.55, rotZ: ang }));
          });
          // horizontal tie between the two legs of this frame
          g.add(box(t, [1.7, 0.1, 0.1], ORANGE, [0, pivotY * 0.45, z], { metal: 0.3, rough: 0.55 }));
          // footing pads
          [-1, 1].forEach((xs) => g.add(box(t, [0.5, 0.12, 0.4], 0x8a8f98, [xs * 1.6, 0.06, z], { tex: 'concrete', rough: 0.9 })));
        });
        // slate cross-beam through the pivot + hub caps
        g.add(cyl(t, 0.09, 0.09, 1.7, SLATE, [0, pivotY, 0], { rotX: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 14 }));
        [-0.72, 0.72].forEach((z) => g.add(cyl(t, 0.14, 0.14, 0.08, ORANGE, [0, pivotY, z], { rotX: Math.PI / 2, metal: 0.4, rough: 0.5, seg: 14 })));

        const swing = new t.Group();
        swing.position.set(0, pivotY, 0);
        g.add(swing);
        // dark centre pole (the sprite hangs the boat from a single slate mast)
        swing.add(box(t, [0.11, 2.5, 0.11], SLATE, [0, -1.25, 0], { metal: 0.5, rough: 0.4 }));
        // magenta counterweight drum near the pivot (visible in the sprite)
        swing.add(cyl(t, 0.24, 0.3, 0.36, 0x6a4423, [0, -0.45, 0], { tex: 'wood', repeat: [3, 1], rough: 0.85, seg: 16 }));

        const boat = new t.Group();
        boat.position.y = -2.5;
        swing.add(boat);
        // magenta hull, layered for a curved profile, orange gunwale trim
        boat.add(box(t, [2.5, 0.34, 0.8], WOOD_D, [0, -0.05, 0], { tex: 'wood', repeat: [8, 1], rough: 0.85 }));
        boat.add(box(t, [2.7, 0.3, 0.88], WOOD, [0, 0.22, 0], { tex: 'wood', repeat: [8, 1], rough: 0.85 }));
        boat.add(box(t, [2.74, 0.07, 0.92], 0xd8b040, [0, 0.4, 0], { metal: 0.4, rough: 0.4 })); // gold gunwale // gunwale
        boat.add(box(t, [2.2, 0.24, 0.7], 0x1c2e2e, [0, 0.34, 0], { rough: 0.85 })); // dark interior well
        // upswept ends + dragon heads at BOTH ends
        [-1, 1].forEach((s) => {
          boat.add(box(t, [0.55, 0.6, 0.8], WOOD, [s * 1.35, 0.35, 0], { tex: 'wood', repeat: [2, 2], rough: 0.85, rotZ: s * 0.55 }));
          const neck = cyl(t, 0.09, 0.14, 0.6, 0x6a4423, [s * 1.72, 0.85, 0], { tex: 'wood', repeat: [1, 2], rough: 0.85, seg: 10, rotZ: s * 0.5 });
          boat.add(neck);
          boat.add(ball(t, 0.17, 0x6a4423, [s * 1.92, 1.12, 0], { tex: 'wood', repeat: [2, 2], flat: true, rough: 0.85 })); // head
          boat.add(box(t, [0.2, 0.09, 0.1], 0x6a4423, [s * 2.08, 1.08, 0], { tex: 'wood', rough: 0.85 })); // snout
          boat.add(ball(t, 0.035, 0xd8b040, [s * 1.98, 1.18, 0.09], { metal: 0.5, rough: 0.3 })); // gold eye // eye
          boat.add(ball(t, 0.035, 0xd8b040, [s * 1.98, 1.18, -0.09], { metal: 0.5, rough: 0.3 }));
        });
        // rows of orange/pink striped seat backs + riders
        for (let i = 0; i < 6; i++) {
          const z0 = -1.0 + i * 0.4;
          boat.add(box(t, [0.06, 0.3, 0.72], i % 2 ? 0xb03030 : 0x8a5a28, [z0, 0.5, 0], { tex: 'wood', repeat: [1, 2], rough: 0.8 })); // red/wood seat backs // seat back (across hull)
          if (i < 5) {
            const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: 'surprised' });
            p.group.scale.setScalar(0.4);
            p.group.position.set(z0 + 0.2, 0.16, 0);
            p.group.rotation.y = Math.PI / 2;
            boat.add(p.group);
          }
        }
        return (time) => {
          swing.rotation.z = Math.sin(time * 1.05) * 0.85;
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Ferris wheel matched to the RCT2 FWH1 sprite: a MAGENTA/PINK spoked wheel
// with lattice cross-bracing between paired rings, an ORANGE outer rim band,
// dark slate-teal lattice A-frame supports, and open two-seat bench gondolas
// (dark teal) that hang inside the rim and stay upright as the wheel turns.
export function FerrisWheel() {
  return (
    <Stage
      distance={9}
      targetY={2.4}
      build={(t, g) => {
        const R = 2.4;
        const cy = 2.7;
        const PINK = 0xd6338c; // wheel spokes/rings (sprite #d03080/#e050a0)
        const ORANGE = 0xe8641c; // outer rim band (sprite #e05020/#f07020)
        const SLATE = 0x3c5454; // support lattice (sprite #305050)
        const SEAT = 0x24383a; // gondola benches

        // A-frame lattice supports (two planes), dark slate like the sprite
        for (const sx of [-1, 1])
          for (const z of [-0.5, 0.5]) {
            const x0 = sx * 1.5;
            const L = Math.hypot(x0, cy);
            const ang = Math.atan2(cy, -x0) - Math.PI / 2;
            g.add(box(t, [0.11, L, 0.11], SLATE, [x0 / 2, cy / 2, z], { tex: 'metal', repeat: [1, 6], metal: 0.4, rough: 0.6, rotZ: ang }));
            // lattice rungs up each leg
            for (let k = 1; k < 5; k++) {
              const yy = (cy * k) / 5;
              const xx = x0 * (1 - k / 5);
              g.add(box(t, [0.32, 0.05, 0.05], SLATE, [xx, yy, z], { metal: 0.4, rough: 0.6 }));
            }
          }
        // cross ties between the two support planes + footing pads
        [-1, 1].forEach((sx) => {
          g.add(box(t, [0.08, 0.08, 1.05], SLATE, [sx * 0.75, cy / 2, 0], { metal: 0.4, rough: 0.6 }));
          [-0.5, 0.5].forEach((z) => g.add(box(t, [0.5, 0.12, 0.4], 0x8a8f98, [sx * 1.5, 0.06, z], { tex: 'concrete', rough: 0.9 })));
        });
        g.add(cyl(t, 0.1, 0.1, 1.16, 0x9aa2ab, [0, cy, 0], { rotX: Math.PI / 2, tex: 'metal', metal: 0.8, rough: 0.3, seg: 16 })); // axle

        const wheel = new t.Group();
        wheel.position.set(0, cy, 0);
        g.add(wheel);

        // paired pink inner rings + ORANGE outer rim rings (slightly larger)
        for (const z of [-0.4, 0.4]) {
          const inner = new t.Mesh(new t.TorusGeometry(R * 0.82, 0.045, 8, 48), new t.MeshStandardMaterial({ color: PINK, metalness: 0.3, roughness: 0.5 }));
          inner.position.z = z;
          inner.castShadow = true;
          wheel.add(inner);
          const outer = new t.Mesh(new t.TorusGeometry(R, 0.055, 8, 48), new t.MeshStandardMaterial({ color: ORANGE, metalness: 0.3, roughness: 0.5 }));
          outer.position.z = z;
          outer.castShadow = true;
          wheel.add(outer);
        }
        // hub discs
        [-0.42, 0.42].forEach((z) => wheel.add(cyl(t, 0.16, 0.16, 0.06, 0x9aa2ab, [0, 0, z], { rotX: Math.PI / 2, metal: 0.7, rough: 0.35, seg: 18 })));

        // 16 pink spokes per plane + lattice cross-bracing between rings
        const NS = 16;
        for (let i = 0; i < NS; i++) {
          const a = (i / NS) * Math.PI * 2;
          [-0.4, 0.4].forEach((z) => {
            wheel.add(box(t, [0.035, R * 2, 0.035], PINK, [0, 0, z], { rotZ: a, metal: 0.3, rough: 0.5 }));
          });
          // radial cross-tie connecting the two planes at the rim
          wheel.add(box(t, [0.05, 0.05, 0.86], PINK, [Math.cos(a + Math.PI / 2) * R * 0.91, Math.sin(a + Math.PI / 2) * R * 0.91, 0], { metal: 0.3, rough: 0.5 }));
          // zig-zag lattice between inner and outer ring (per plane)
          [-0.4, 0.4].forEach((z) => {
            const mid = (R * 0.82 + R) / 2;
            wheel.add(box(t, [0.03, 0.42, 0.03], PINK, [Math.cos(a + Math.PI / 2 + 0.1) * mid, Math.sin(a + Math.PI / 2 + 0.1) * mid, z], { rotZ: a + 0.5, metal: 0.3, rough: 0.5 }));
          });
        }

        // 8 open bench gondolas, dark teal, hanging inside the rim, kept upright
        const N = 8;
        const gondolas: ReturnType<typeof buildPeep>['group'][] = [];
        for (let i = 0; i < N; i++) {
          const gd = new t.Group();
          gd.add(box(t, [0.46, 0.07, 0.4], SEAT, [0, -0.16, 0], { rough: 0.8 })); // bench seat
          gd.add(box(t, [0.46, 0.3, 0.06], SEAT, [0, -0.02, -0.17], { rough: 0.8 })); // seat back
          gd.add(box(t, [0.46, 0.05, 0.05], ORANGE, [0, 0.06, 0.16], { rough: 0.5 })); // safety bar
          [-0.2, 0.2].forEach((x) => gd.add(box(t, [0.04, 0.34, 0.04], SLATE, [x, 0.06, 0], { metal: 0.4, rough: 0.6 }))); // hangers
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.set(0, -0.33, 0.02);
          gd.add(p.group);
          g.add(gd);
          gondolas.push(gd as never);
        }
        return (time) => {
          wheel.rotation.z = time * 0.35;
          for (let i = 0; i < N; i++) {
            const a = (i / N) * Math.PI * 2 + wheel.rotation.z;
            const gd = gondolas[i] as unknown as { position: { set: (x: number, y: number, z: number) => void }; rotation: { z: number } };
            gd.position.set(Math.cos(a) * R * 0.88, cy + Math.sin(a) * R * 0.88, 0);
            gd.rotation.z = Math.sin(time * 2 + i) * 0.06; // gentle sway, stays upright
          }
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Roto-drop tower matched to the RCT2 GDROP1 sprite: the gondola is a dark
// slate-TEAL core drum ringed by outward-facing riders whose legs dangle, with
// PINK seat backs, an ORANGE canopy ring above and orange kick plates below.
// It climbs a pale lattice tower slowly, spins, then plummets.
export function DropTower() {
  return (
    <Stage
      distance={9}
      targetY={2.6}
      build={(t, g) => {
        const H = 5.4;
        const TEAL = 0x2e4444; // core drum (sprite #203030/#305050)
        const ORANGE = 0xe8641c; // canopy + trim
        const PINK = 0xd6338c; // seat backs
        const LATTICE = 0xc9ccd2; // pale tower steel

        g.add(cyl(t, 0.75, 0.85, 0.4, 0x8a8f98, [0, 0.2, 0], { tex: 'concrete', repeat: [6, 1], rough: 0.9, seg: 24 }));
        // pale square lattice tower: 4 corner chords + rungs + diagonals
        const cs = 0.26;
        [-cs, cs].forEach((x) =>
          [-cs, cs].forEach((z) => g.add(box(t, [0.07, H, 0.07], LATTICE, [x, H / 2, z], { tex: 'metal', metal: 0.5, rough: 0.4 }))),
        );
        for (let y = 0.5; y < H; y += 0.45) {
          [-cs, cs].forEach((z) => g.add(box(t, [cs * 2, 0.045, 0.045], LATTICE, [0, y, z], { metal: 0.5, rough: 0.4 })));
          [-cs, cs].forEach((x) => g.add(box(t, [0.045, 0.045, cs * 2], LATTICE, [x, y, 0], { metal: 0.5, rough: 0.4 })));
          g.add(box(t, [cs * 2.7, 0.04, 0.04], LATTICE, [0, y + 0.22, cs], { rotZ: 0.7, metal: 0.5, rough: 0.4 }));
          g.add(box(t, [cs * 2.7, 0.04, 0.04], LATTICE, [0, y + 0.22, -cs], { rotZ: -0.7, metal: 0.5, rough: 0.4 }));
        }
        g.add(cyl(t, 0, 0.4, 0.5, ORANGE, [0, H + 0.2, 0], { seg: 6, rough: 0.5 })); // orange cap

        const gondola = new t.Group();
        g.add(gondola);
        // teal core drum + orange canopy ring above + orange kick ring below
        gondola.add(cyl(t, 0.42, 0.42, 0.5, TEAL, [0, 0.15, 0], { tex: 'metal', metal: 0.3, rough: 0.6, seg: 22 }));
        gondola.add(cyl(t, 0.8, 0.68, 0.12, ORANGE, [0, 0.48, 0], { rough: 0.5, seg: 22 })); // canopy
        gondola.add(cyl(t, 0.84, 0.84, 0.04, PINK, [0, 0.54, 0], { rough: 0.5, seg: 22 })); // pink canopy lip
        gondola.add(cyl(t, 0.66, 0.72, 0.08, ORANGE, [0, -0.14, 0], { rough: 0.5, seg: 22 })); // kick ring
        // 10 outward-facing riders: pink seat back, dangling legs (seated peeps)
        const N = 10;
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          const seat = new t.Group();
          seat.position.set(Math.cos(a) * 0.56, 0, Math.sin(a) * 0.56);
          seat.rotation.y = -a - Math.PI / 2; // face outward
          seat.add(box(t, [0.26, 0.4, 0.06], PINK, [0, 0.22, -0.1], { rough: 0.55 })); // seat back
          seat.add(box(t, [0.26, 0.06, 0.2], TEAL, [0, 0.0, 0], { rough: 0.6 })); // seat pan
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.34);
          p.group.position.set(0, -0.17, 0.04);
          seat.add(p.group);
          seat.add(box(t, [0.2, 0.04, 0.04], TEAL, [0, 0.24, 0.12], { metal: 0.5, rough: 0.4 })); // lap bar
          gondola.add(seat);
        }
        return (time) => {
          const cyc = (time * 0.3) % 1;
          const h = cyc < 0.8 ? cyc / 0.8 : 1 - (cyc - 0.8) / 0.2; // slow climb, fast drop
          gondola.position.y = 0.75 + h * (H - 1.5);
          gondola.rotation.y = time * (cyc < 0.8 ? 0.8 : 2.2); // spins, faster on the drop
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SKIN_TONES } from '../Guest';

// Merry-go-round matched to the RCT2 MGR1 sprite: a flat conical canopy with
// ORANGE/WHITE pinwheel stripes and a scalloped orange rim, a green+gold
// decorated frieze band, WHITE horses with pink saddles on gold poles, a tan
// wooden deck, and stacked orange ring steps at the base.
export function Carousel() {
  return (
    <Stage
      distance={6.8}
      targetY={1.05}
      build={(t, g) => {
        const ORANGE = 0xe8641c;
        const CREAM = 0xdad4c8; // canopy white (sprite #d0d0d0)
        const TAN = 0x9a8456; // deck wood (sprite #605030 lit)
        const GREEN = 0x4c6e30; // frieze trim
        const GOLD = 0xd8b040;
        const HORSE = 0xf0ece4; // white horses
        const SADDLE = 0xd6338c; // pink saddles

        // stacked orange ring steps at the base (sprite shows 2-3 ledges)
        g.add(cyl(t, 1.78, 1.86, 0.1, ORANGE, [0, 0.05, 0], { rough: 0.7, seg: 36 }));
        g.add(cyl(t, 1.68, 1.76, 0.1, 0xc44a14, [0, 0.15, 0], { rough: 0.7, seg: 36 }));
        g.add(cyl(t, 1.6, 1.66, 0.08, ORANGE, [0, 0.24, 0], { rough: 0.7, seg: 36 }));

        const ride = new t.Group();
        g.add(ride);
        // tan wooden deck
        ride.add(cyl(t, 1.52, 1.52, 0.1, TAN, [0, 0.33, 0], { tex: 'wood', repeat: [10, 1], rough: 0.85, seg: 36 }));
        // centre drum, gold-trimmed with mirrored panels
        ride.add(cyl(t, 0.34, 0.34, 1.35, 0xb8a070, [0, 1.05, 0], { tex: 'wood', repeat: [6, 2], rough: 0.7, seg: 20 }));
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          ride.add(box(t, [0.1, 0.5, 0.02], GOLD, [Math.cos(a) * 0.35, 1.05, Math.sin(a) * 0.35], { metal: 0.6, rough: 0.3, rotY: -a }));
        }

        // pinwheel canopy: alternating orange/white wedge segments (flat cone)
        const SEGS = 16;
        for (let i = 0; i < SEGS; i++) {
          const a0 = (i / SEGS) * Math.PI * 2;
          const wedge = new t.Mesh(
            new t.CylinderGeometry(0.04, 1.78, 0.5, 3, 1, false, a0, (Math.PI * 2) / SEGS),
            new t.MeshStandardMaterial({ color: i % 2 ? ORANGE : CREAM, roughness: 0.6 }),
          );
          wedge.position.y = 2.12;
          wedge.castShadow = true;
          ride.add(wedge);
        }
        // scalloped orange rim band under the canopy edge
        ride.add(cyl(t, 1.8, 1.8, 0.1, ORANGE, [0, 1.88, 0], { rough: 0.6, seg: 36 }));
        for (let i = 0; i < 18; i++) {
          const a = (i / 18) * Math.PI * 2;
          ride.add(ball(t, 0.08, ORANGE, [Math.cos(a) * 1.8, 1.82, Math.sin(a) * 1.8], { flat: true, rough: 0.6 })); // scallops
        }
        // green + gold frieze ring
        ride.add(cyl(t, 1.72, 1.72, 0.07, GREEN, [0, 1.79, 0], { rough: 0.7, seg: 36 }));
        ride.add(cyl(t, 1.74, 1.74, 0.03, GOLD, [0, 1.74, 0], { metal: 0.6, rough: 0.3, seg: 36 }));
        // finial on top
        ride.add(cyl(t, 0.02, 0.02, 0.5, GOLD, [0, 2.55, 0], { metal: 0.7, rough: 0.3, seg: 8 }));
        ride.add(ball(t, 0.09, GOLD, [0, 2.8, 0], { metal: 0.7, rough: 0.3 }));

        // 8 white horses with pink saddles on gold poles, alternating riders
        const horses: { grp: THREE.Group; ph: number }[] = [];
        const N = 8;
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          const hg = new t.Group();
          hg.position.set(Math.cos(a) * 1.12, 0.92, Math.sin(a) * 1.12);
          hg.rotation.y = -a + Math.PI / 2;
          hg.add(cyl(t, 0.022, 0.022, 1.5, GOLD, [0, 0.3, 0], { tex: 'metal', metal: 0.85, rough: 0.2, seg: 10 }));
          // horse: body, chest, neck, head, muzzle, legs mid-gallop, tail
          hg.add(box(t, [0.48, 0.2, 0.17], HORSE, [0, 0, 0], { rough: 0.55 }));
          hg.add(ball(t, 0.11, HORSE, [0.24, 0.02, 0], { rough: 0.55 })); // chest
          hg.add(box(t, [0.13, 0.24, 0.12], HORSE, [0.27, 0.17, 0], { rough: 0.55, rotZ: -0.3 })); // neck
          hg.add(box(t, [0.18, 0.11, 0.11], HORSE, [0.37, 0.3, 0], { rough: 0.55 })); // head
          hg.add(box(t, [0.09, 0.07, 0.08], 0xd8cfc0, [0.46, 0.28, 0], { rough: 0.55 })); // muzzle
          hg.add(box(t, [0.28, 0.05, 0.02], SADDLE, [-0.02, 0.11, 0.09], { rough: 0.6 })); // saddle blanket
          hg.add(box(t, [0.28, 0.05, 0.02], SADDLE, [-0.02, 0.11, -0.09], { rough: 0.6 }));
          hg.add(box(t, [0.2, 0.05, 0.17], SADDLE, [-0.02, 0.12, 0], { rough: 0.6 })); // saddle
          // galloping legs (front pair forward, rear pair back)
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [0.19, -0.19, 0.05], { rough: 0.55, rotZ: 0.5 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [0.19, -0.19, -0.05], { rough: 0.55, rotZ: 0.3 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [-0.19, -0.19, 0.05], { rough: 0.55, rotZ: -0.5 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [-0.19, -0.19, -0.05], { rough: 0.55, rotZ: -0.3 }));
          hg.add(box(t, [0.14, 0.05, 0.04], 0xd8cfc0, [-0.29, 0.06, 0], { rough: 0.55, rotZ: 0.5 })); // tail
          if (i % 2 === 0) {
            const p = buildPeep(t, { skin: SKIN_TONES[(i / 2) % SKIN_TONES.length], shirt: [0x3aa0e0, 0xe0a020, 0x2e9e54, 0xd6338c][(i / 2) % 4], seated: true });
            p.group.scale.setScalar(0.42);
            p.group.position.set(-0.02, -0.04, 0);
            p.group.rotation.y = -Math.PI / 2;
            hg.add(p.group);
          }
          ride.add(hg);
          horses.push({ grp: hg, ph: a });
        }
        return (time) => {
          ride.rotation.y = time * 0.55;
          horses.forEach((hh) => (hh.grp.position.y = 0.92 + Math.sin(time * 3 + hh.ph * 2) * 0.11));
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Log flume modelled from the RCT2 water ride: an elevated wooden trough of
// blue water on posts, with a hollow log boat of riders sliding along it.
export function LogFlume() {
  return (
    <Stage
      distance={7.5}
      targetY={0.9}
      background="#bfe6f2"
      build={(t, g) => {
        const RUN = 6.4;
        g.add(box(t, [1.0, 0.16, RUN], 0x5a3d22, [0, 0.6, 0], { tex: 'wood', repeat: [4, 22], rough: 0.8 }));
        [-0.5, 0.5].forEach((x) => g.add(box(t, [0.1, 0.34, RUN], 0x4a3018, [x, 0.76, 0], { tex: 'wood', repeat: [1, 22], rough: 0.8 })));
        g.add(box(t, [0.84, 0.06, RUN], 0x2a8fd0, [0, 0.74, 0], { emissive: 0x115f9c, rough: 0.2, opacity: 0.9 })); // water
        for (let z = -RUN / 2 + 0.5; z < RUN / 2; z += 1.4)
          [-0.5, 0.5].forEach((x) => g.add(cyl(t, 0.08, 0.09, 0.7, 0x5a3d22, [x, 0.25, z], { tex: 'wood', repeat: [1, 1], rough: 1, seg: 8 })));

        const boat = new t.Group();
        g.add(boat);
        boat.add(cyl(t, 0.3, 0.3, 1.2, 0x8a5a28, [0, 0, 0], { rotX: Math.PI / 2, tex: 'wood', repeat: [6, 2], rough: 0.9, seg: 18 })); // bark barrel (along z)
        boat.add(ball(t, 0.3, 0x8a5a28, [0, 0, 0.6], { tex: 'wood', repeat: [3, 3], flat: true, rough: 0.9 })); // rounded nose
        boat.add(ball(t, 0.3, 0x8a5a28, [0, 0, -0.6], { tex: 'wood', repeat: [3, 3], flat: true, rough: 0.9 })); // rounded tail
        boat.add(box(t, [0.5, 0.06, 1.24], 0xe8cc80, [0, 0.16, 0], { rough: 0.7 })); // cream cut rim
        boat.add(box(t, [0.4, 0.18, 1.1], 0x2a1c10, [0, 0.12, 0], { rough: 0.9 })); // hollowed interior
        for (let i = 0; i < 3; i++) {
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[(i + 3) % SHIRTS.length], seated: true, expression: i === 0 ? 'surprised' : 'happy' });
          p.group.scale.setScalar(0.42);
          p.group.position.set(0, 0.02, -0.42 + i * 0.42);
          boat.add(p.group);
        }
        return (time) => {
          const z = ((time * 1.4) % (RUN + 1.5)) - (RUN / 2 + 0.75);
          boat.position.set(0, 0.86, z);
        };
      }}
    />
  );
}
